module miss_handler import ariane_pkg::*; #(
    parameter int unsigned NR_PORTS = 3
)(
...
);

    // FSM states
    enum logic [3:0] {
        IDLE, FLUSHING, FLUSH, WB_CACHELINE, MISS, MISS_REPL, REQ_CACHELINE,
        WAIT_GNT, SERVING_MISS, WAIT_BYPASS_GNT, WAIT_BYPASS_VALID,
        AMO_REQ, AMO_WAIT_RESP
    } state_d, state_q;

    // MSHR
    mshr_t mshr_d, mshr_q;
    logic mshr_valid_d, mshr_valid_q;

